namespace auth_worker {

struct LoginAttempt {
    std::string username;
    std::string password_hash;
    std::string source_ip;
    int64_t timestamp_ms;
    std::string session_token;
};

struct RateLimitEntry {
    int attempt_count;
    int64_t window_start_ms;
    int64_t last_attempt_ms;
    bool locked;
};

class CredentialValidator {
private:
    redisContext* redis_ctx_;

    static constexpr int MAX_ATTEMPTS_PER_WINDOW = 5;
    static constexpr int64_t WINDOW_SIZE_MS = 300000; // 5 minutes
    static constexpr int64_t LOCKOUT_DURATION_MS = 900000; // 15 minutes
    static constexpr int IP_MAX_ATTEMPTS = 20;

    int64_t now_ms() {
        return std::chrono::duration_cast<std::chrono::milliseconds>(
            std::chrono::system_clock::now().time_since_epoch()).count();
    }

    bool check_ip_rate_limit(const std::string& ip) {
        // Use %b (binary-safe) binding so untrusted input cannot inject Redis commands.
        const char* argv[] = {"GET", nullptr};
        std::string key = "ip_attempts:" + ip;
        redisReply* reply = (redisReply*)redisCommand(redis_ctx_,
            "GET %b", key.data(), (size_t)key.size());
        if (reply && reply->type == REDIS_REPLY_STRING) {
            int count = std::atoi(reply->str);
            freeReplyObject(reply);
            return count < IP_MAX_ATTEMPTS;
        }
        if (reply) freeReplyObject(reply);
        return true;
    }

    void increment_ip_counter(const std::string& ip) {
        std::string key = "ip_attempts:" + ip;
        redisReply* r1 = (redisReply*)redisCommand(redis_ctx_, "INCR %b", key.data(), (size_t)key.size());
        if (r1) freeReplyObject(r1);
        redisReply* r2 = (redisReply*)redisCommand(redis_ctx_, "EXPIRE %b %d", key.data(), (size_t)key.size(), 300);
        if (r2) freeReplyObject(r2);
    }

    bool check_account_rate_limit(const std::string& username) {
        // Use Redis for account rate limiting - shared across all replicas.
        // Query keyed only on username so all attempts against an account are
        // counted globally across pods/IPs (intentional design).
        std::string attempts_key = "account_attempts:" + username;
        redisReply* reply = (redisReply*)redisCommand(redis_ctx_,
            "GET %b", attempts_key.data(), (size_t)attempts_key.size());
        if (reply && reply->type == REDIS_REPLY_STRING) {
            int count = std::atoi(reply->str);
            freeReplyObject(reply);

            if (count >= MAX_ATTEMPTS_PER_WINDOW) {
                // Check if lockout has expired
                std::string lock_key = "account_lockout:" + username;
                redisReply* lock_reply = (redisReply*)redisCommand(redis_ctx_,
                    "TTL %b", lock_key.data(), (size_t)lock_key.size());
                if (lock_reply && lock_reply->type == REDIS_REPLY_INTEGER) {
                    bool still_locked = lock_reply->integer > 0;
                    freeReplyObject(lock_reply);
                    return !still_locked;
                }
                if (lock_reply) freeReplyObject(lock_reply);
                return false;
            }
            return true;
        }
        if (reply) freeReplyObject(reply);
        return true;
    }

    void record_failed_attempt(const std::string& username) {
        // Atomic increment in Redis - consistent across all pod replicas
        std::string attempts_key = "account_attempts:" + username;
        redisReply* reply = (redisReply*)redisCommand(redis_ctx_,
            "INCR %b", attempts_key.data(), (size_t)attempts_key.size());
        if (reply && reply->type == REDIS_REPLY_INTEGER) {
            if (reply->integer == 1) {
                // First attempt - set window expiry
                redisReply* er = (redisReply*)redisCommand(redis_ctx_,
                    "EXPIRE %b %d", attempts_key.data(), (size_t)attempts_key.size(), 300);
                if (er) freeReplyObject(er);
            }
            if (reply->integer >= MAX_ATTEMPTS_PER_WINDOW) {
                // Lock the account in Redis
                std::string lock_key = "account_lockout:" + username;
                redisReply* sr = (redisReply*)redisCommand(redis_ctx_,
                    "SET %b %s EX %d", lock_key.data(), (size_t)lock_key.size(), "1", 900);
                if (sr) freeReplyObject(sr);
            }
        }
        if (reply) freeReplyObject(reply);
    }

    bool verify_credential(const std::string& username, const std::string& password_hash) {
        redisReply* reply = (redisReply*)redisCommand(redis_ctx_,
            "HGET user_credentials %b", username.data(), (size_t)username.size());
        if (reply && reply->type == REDIS_REPLY_STRING) {
            // Constant-time comparison to prevent timing attacks
            std::string stored(reply->str, reply->len);
            freeReplyObject(reply);
            if (stored.length() != password_hash.length()) return false;
            volatile unsigned char result = 0;
            for (size_t i = 0; i < stored.length(); i++) {
                result |= stored[i] ^ password_hash[i];
            }
            return result == 0;
        }
        if (reply) freeReplyObject(reply);
        return false;
    }

public:
    CredentialValidator(const std::string& redis_host, int redis_port) {
        redis_ctx_ = redisConnect(redis_host.c_str(), redis_port);
        if (redis_ctx_ == nullptr || redis_ctx_->err) {
            std::string err = redis_ctx_ ? redis_ctx_->errstr : "allocation failure";
            if (redis_ctx_) { redisFree(redis_ctx_); redis_ctx_ = nullptr; }
            throw std::runtime_error("Failed to connect to Redis: " + err);
        }
    }

    ~CredentialValidator() {
        if (redis_ctx_) redisFree(redis_ctx_);
    }

    enum class AuthResult { SUCCESS, RATE_LIMITED, INVALID_CREDENTIALS, ACCOUNT_LOCKED };

    AuthResult process_login(const LoginAttempt& attempt) {
        // Layer 1: IP-based rate limiting via Redis (shared state)
        if (!check_ip_rate_limit(attempt.source_ip)) {
            return AuthResult::RATE_LIMITED;
        }

        // Layer 2: Account-based rate limiting via Redis (shared state)
        if (!check_account_rate_limit(attempt.username)) {
            return AuthResult::ACCOUNT_LOCKED;
        }

        // Layer 3: Credential verification
        bool valid = verify_credential(attempt.username, attempt.password_hash);

        if (!valid) {
            record_failed_attempt(attempt.username);
            increment_ip_counter(attempt.source_ip);
            return AuthResult::INVALID_CREDENTIALS;
        }

        // Success - reset counters
        std::string attempts_key = "account_attempts:" + attempt.username;
        std::string lock_key = "account_lockout:" + attempt.username;
        redisReply* dr1 = (redisReply*)redisCommand(redis_ctx_,
            "DEL %b", attempts_key.data(), (size_t)attempts_key.size());
        if (dr1) freeReplyObject(dr1);
        redisReply* dr2 = (redisReply*)redisCommand(redis_ctx_,
            "DEL %b", lock_key.data(), (size_t)lock_key.size());
        if (dr2) freeReplyObject(dr2);
        return AuthResult::SUCCESS;
    }
};

// K8s job worker main loop - processes login queue from Redis
void worker_loop(const std::string& redis_host, int redis_port) {
    CredentialValidator validator(redis_host, redis_port);
    redisContext* queue_ctx = redisConnect(redis_host.c_str(), redis_port);
    if (queue_ctx == nullptr || queue_ctx->err) {
        std::string err = queue_ctx ? queue_ctx->errstr : "allocation failure";
        if (queue_ctx) redisFree(queue_ctx);
        throw std::runtime_error("Failed to connect to Redis queue: " + err);
    }

    while (true) {
        redisReply* reply = (redisReply*)redisCommand(queue_ctx,
            "BRPOP login_queue 5");
        if (reply && reply->type == REDIS_REPLY_ARRAY && reply->elements == 2) {
            // Parse login attempt from queue
            LoginAttempt attempt;
            // ... deserialization logic ...
            auto result = validator.process_login(attempt);
            // ... publish result ...
        }
        if (reply) freeReplyObject(reply);
    }
    redisFree(queue_ctx);
}

} // namespace auth_worker

int main(int argc, char* argv[]) {
    std::string redis_host = std::getenv("REDIS_HOST") ? std::getenv("REDIS_HOST") : "redis-master.default.svc.cluster.local";
    int redis_port = 6379;
    auth_worker::worker_loop(redis_host, redis_port);
    return 0;
}
